using System;
using ObjCRuntime;
using Foundation;

namespace Net.Agora.Voice.iOS {

	// Hand-written against the real AgoraRtcKit.xcframework headers from AgoraAudio_iOS 4.6.2
	// (io.agora.rtc:voice-rtc-basic's iOS counterpart) rather than generated by Objective Sharpie —
	// same reasoning as Net.Agora.Video.iOS's ApiDefinition.cs: sharpie's bundled clang cannot
	// parse SDKs from current Xcode. The voice pod ships the same AgoraRtcKit framework name and
	// headers as the video pod, with the video pipeline stripped from the binary.
	//
	// Scoped to what the thin Net.Agora.Voice client needs — create the engine, join/leave a
	// channel, publish/mute audio, drive the audio route, report speaker volumes, and the delegate
	// callbacks for those — not the SDK's full surface. The video entry points the shared headers
	// also declare are deliberately not bound: the native voice engine cannot perform them, so a
	// binding that compiled them would only convert build-time certainty into runtime error codes.
	// Extend here as more of AgoraRtcEngineKit.h is needed. Enums live in StructsAndEnums.cs; the
	// block delegate types stay here — the binding generator emits a trampoline for a delegate
	// declared in the api definition file itself, and duplicates it if the same type is declared
	// again in the core source file.

	// Objective-C blocks used as completion handlers on AgoraRtcEngineKit (AgoraRtcEngineKit.h).
	public delegate void AgoraJoinChannelSuccessHandler (string channel, nuint uid, nint elapsed);
	public delegate void AgoraLeaveChannelHandler (AgoraChannelStats stats);

	// AgoraChannelStats — AgoraObjects.h. Bound as an opaque type: it is only used here as the
	// LeaveChannel completion handler's parameter type. Add properties as callers need the stats.
	[BaseType (typeof (NSObject))]
	public interface AgoraChannelStats {
	}

	// AgoraRtcEngineConfig — AgoraObjects.h. Only the two properties every engine needs.
	[BaseType (typeof (NSObject))]
	public interface AgoraRtcEngineConfig {
		[Export ("appId", ArgumentSemantic.Copy)]
		[NullAllowed]
		string AppId { get; set; }

		[Export ("channelProfile")]
		AgoraChannelProfile ChannelProfile { get; set; }
	}

	// AgoraRtcAudioVolumeInfo — AgoraObjects.h. One speaker's entry in the volume indication
	// callback: uid 0 is the local user in the local callback, volume ranges 0–255.
	[BaseType (typeof (NSObject))]
	public interface AgoraRtcAudioVolumeInfo {
		[Export ("uid")]
		nuint Uid { get; set; }

		[Export ("volume")]
		nuint Volume { get; set; }
	}

	// Delegates/Events: the generator turns every AgoraRtcEngineDelegate callback into a C# event
	// on the engine (engine.DidJoinChannel += …), backed by an internal delegate it installs via
	// the `delegate` property the first time an event is subscribed. One caveat inherited from
	// how Apple bindings do this everywhere: events and a hand-assigned Delegate are mutually
	// exclusive — subscribing an event replaces whatever delegate was set (including the one
	// passed to SharedEngine), and assigning Delegate afterwards silently detaches the events.
	// Pick one style per engine instance.
	[BaseType (typeof (NSObject), Delegates = new [] { "WeakDelegate" }, Events = new [] { typeof (AgoraRtcEngineDelegate) })]
	[DisableDefaultCtor] // The engine only exists through SharedEngine — `new AgoraRtcEngineKit()`
	                     // compiled before this and handed back a broken non-shared instance.
	public interface AgoraRtcEngineKit {

		// + (instancetype)sharedEngineWithConfig:delegate:
		[Static]
		[Export ("sharedEngineWithConfig:delegate:")]
		AgoraRtcEngineKit SharedEngine (AgoraRtcEngineConfig config, [NullAllowed] AgoraRtcEngineDelegate del);

		// + (void)destroy — call after releasing every reference to the shared instance.
		[Static]
		[Export ("destroy")]
		void Destroy ();

		// @property(nonatomic, weak) id<AgoraRtcEngineDelegate> delegate — the property behind
		// SharedEngine's second argument. Weak: the engine does not root the delegate, so keep a
		// reference alive on the caller's side or the callbacks stop with no error.
		[Export ("delegate", ArgumentSemantic.Weak)]
		[NullAllowed]
		NSObject WeakDelegate { get; set; }

		[Wrap ("WeakDelegate")]
		[NullAllowed]
		AgoraRtcEngineDelegate Delegate { get; set; }

		// - (int)joinChannelByToken:channelId:info:uid:joinSuccess: — deliberately no [Async] here
		// or on LeaveChannel, matching Video. The generator would take it (it emits an Async
		// overload plus an `out nint` one for the return code), but these blocks are success-only
		// callbacks, not completions: on a failed join the block never fires and the generated
		// Task would never complete. Failures arrive as the return code and on the delegate.
		[Export ("joinChannelByToken:channelId:info:uid:joinSuccess:")]
		nint JoinChannel ([NullAllowed] string token, string channelId, [NullAllowed] string info, nuint uid, [NullAllowed] AgoraJoinChannelSuccessHandler joinSuccess);

		// - (int)leaveChannel:(void(^)(AgoraChannelStats*))
		[Export ("leaveChannel:")]
		nint LeaveChannel ([NullAllowed] AgoraLeaveChannelHandler leaveChannelBlock);

		[Export ("setChannelProfile:")]
		nint SetChannelProfile (AgoraChannelProfile profile);

		[Export ("setClientRole:")]
		nint SetClientRole (AgoraClientRole role);

		[Export ("enableAudio")]
		nint EnableAudio ();

		[Export ("disableAudio")]
		nint DisableAudio ();

		[Export ("muteLocalAudioStream:")]
		nint MuteLocalAudioStream (bool mute);

		// - (int)renewToken: — the other half of the DidRequestToken/TokenPrivilegeWillExpire
		// callbacks below.
		[Export ("renewToken:")]
		nint RenewToken (string token);

		// Audio route. setDefaultAudioRouteToSpeakerphone: picks the default before joining;
		// setEnableSpeakerphone: overrides it live in the channel — AgoraRtcEngineKit.h documents
		// both and the interplay between them.
		[Export ("setDefaultAudioRouteToSpeakerphone:")]
		nint SetDefaultAudioRouteToSpeakerphone (bool defaultToSpeaker);

		[Export ("setEnableSpeakerphone:")]
		nint SetEnableSpeakerphone (bool enableSpeaker);

		// - (int)enableAudioVolumeIndication:smooth:reportVad: — interval in ms; smooth is the
		// smoothing factor (the header recommends 3). The header claims interval <= 0 disables,
		// but the 4.6.2 engine answers -2 (invalid argument) to 0 — don't rely on it.
		// - (int)enableAudioVolumeIndication:smooth:reportVad: — interval in ms; smooth is the
		// smoothing factor (the header recommends 3). The header claims interval <= 0 disables,
		// but the 4.6.2 engine answers -2 (invalid argument) to 0 — don't rely on it.
		[Export ("enableAudioVolumeIndication:smooth:reportVad:")]
		nint EnableAudioVolumeIndication (nint interval, nint smooth, bool reportVad);

		// ------------------------------------------------------------------------------------
		// Extension controls
		// ------------------------------------------------------------------------------------
		// These switches all live on the engine and are therefore always callable — but each one
		// only *works* when the matching extension framework is in the app bundle, which is what
		// the Net.Agora.Extensions.*.iOS packages carry. Without it the engine answers a failure
		// code from a call that compiled and linked perfectly; see src/Agora.Extension.md.

		// - (int)setAINSMode:mode: — the AI noise suppressor
		// (Net.Agora.Extensions.Ains.iOS).
		[Export ("setAINSMode:mode:")]
		nint SetAinsMode (bool enabled, AgoraAinsMode mode);

		// - (int)setVoiceBeautifierPreset: and - (int)setAudioEffectPreset: — the voice changers
		// and room reverbs (Net.Agora.Extensions.AudioBeauty.iOS). The two overwrite each other;
		// AgoraRtcEngineKit.h spells out the interplay.
		[Export ("setVoiceBeautifierPreset:")]
		nint SetVoiceBeautifierPreset (AgoraVoiceBeautifierPreset preset);

		[Export ("setAudioEffectPreset:")]
		nint SetAudioEffectPreset (AgoraAudioEffectPreset preset);

		// The video-only filters (virtual background, the ClearVision image-quality options, face
		// detection) are deliberately absent here: this is the voice build of AgoraRtcKit, which
		// has no video pipeline for them to act on. They are bound in Net.Agora.Video.iOS.
	}

	// AgoraRtcEngineDelegate — AgoraRtcEngineDelegate.h. Every method there is @optional; scoped
	// here to the callbacks the thin wrapper turns into C# events.
	[Protocol]
	[Model]
	[BaseType (typeof (NSObject))]
	public interface AgoraRtcEngineDelegate {

		// The [EventArgs] names below become public <name>EventArgs classes (the generator
		// appends the suffix) feeding the events on AgoraRtcEngineKit — part of the package's
		// API surface, so renaming one is a breaking change. They are deliberately the same
		// names Net.Agora.Video.iOS uses for the callbacks both products share (the namespaces
		// differ, so nothing collides): an app moving between Voice and Video should find the
		// two engines identical wherever their surfaces overlap.

		[Export ("rtcEngine:didJoinChannel:withUid:elapsed:")]
		[EventArgs ("AgoraRtcDidJoinChannel")]
		void DidJoinChannel (AgoraRtcEngineKit engine, string channel, nuint uid, nint elapsed);

		[Export ("rtcEngine:didLeaveChannelWithStats:")]
		[EventArgs ("AgoraRtcDidLeaveChannel")]
		void DidLeaveChannel (AgoraRtcEngineKit engine, AgoraChannelStats stats);

		[Export ("rtcEngine:didJoinedOfUid:elapsed:")]
		[EventArgs ("AgoraRtcRemoteUserJoined")]
		void DidJoinedOfUid (AgoraRtcEngineKit engine, nuint uid, nint elapsed);

		[Export ("rtcEngine:didOfflineOfUid:reason:")]
		[EventArgs ("AgoraRtcRemoteUserOffline")]
		void DidOfflineOfUid (AgoraRtcEngineKit engine, nuint uid, AgoraUserOfflineReason reason);

		[Export ("rtcEngine:didOccurError:")]
		[EventArgs ("AgoraRtcErrorOccurred")]
		void DidOccurError (AgoraRtcEngineKit engine, AgoraErrorCode errorCode);

		// A remote user muting/unmuting their audio — the voice UI's "who is muted" signal.
		[Export ("rtcEngine:didAudioMuted:byUid:")]
		[EventArgs ("AgoraRtcRemoteAudioMuted")]
		void DidAudioMuted (AgoraRtcEngineKit engine, bool muted, nuint uid);

		// Speaker volumes, at the cadence EnableAudioVolumeIndication configured. The speakers
		// array carries the loudest few; uid 0 means the local user in the local callback.
		[Export ("rtcEngine:reportAudioVolumeIndicationOfSpeakers:totalVolume:")]
		[EventArgs ("AgoraRtcAudioVolumeIndicated")]
		void ReportAudioVolumeIndication (AgoraRtcEngineKit engine, AgoraRtcAudioVolumeInfo[] speakers, nint totalVolume);

		// - (void)rtcEngine:tokenPrivilegeWillExpire: — fire RenewToken from here.
		[Export ("rtcEngine:tokenPrivilegeWillExpire:")]
		[EventArgs ("AgoraRtcTokenPrivilegeWillExpire")]
		void TokenPrivilegeWillExpire (AgoraRtcEngineKit engine, string token);

		// The connection lifecycle (connecting/connected/reconnecting/...). The reason parameter
		// is AgoraConnectionChangedReason — ~30 values; carried as its raw NSInteger rather than
		// binding an enum consumers would mostly pass through as a number anyway.
		[Export ("rtcEngine:connectionChangedToState:reason:")]
		[EventArgs ("AgoraRtcConnectionChanged")]
		void ConnectionChangedToState (AgoraRtcEngineKit engine, AgoraConnectionState state, nint reason);
	}
}
